const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

if (isMainThread) {
  // Main thread: spawn two worker threads (true parallelism in Node.js)
  const results = [];

  function runWorker(data) {
    return new Promise((resolve, reject) => {
      const worker = new Worker(__filename, { workerData: data });
      worker.on('message', resolve);
      worker.on('error', reject);
    });
  }

  Promise.all([
    runWorker({ task: 'A', iterations: 5e6 }),
    runWorker({ task: 'B', iterations: 5e6 })
  ]).then(([a, b]) => {
    console.log('Task A:', a); // Task A: done in ~Xms
    console.log('Task B:', b); // Task B: done in ~Xms
    // Both ran in PARALLEL — total time ≈ one task, not two
  });
} else {
  // Worker thread: CPU-bound work without blocking main thread
  let count = 0;
  const start = Date.now();
  for (let i = 0; i < workerData.iterations; i++) count += i;
  parentPort.postMessage(`done in ${Date.now() - start}ms (sum=${count})`);
}

